// SETTINGS: edit these two lines.
const MY_ADDRESS = 'you@gmail.com'; // your Gmail address (the agent skips its own digest emails)
const DEMO_MODE = true; // true = only the demo inbox (.example senders) goes to the AI. Set false for your
                        // own mail, and use Gemini's PAID tier for real mail (free-tier inputs may be used
                        // to improve Google's products).
// Keep what the sorter needs. DEMO MODE: only the seeded demo senders (.example addresses) go further, so no
// real mail is ever sent to the model; the agent's own digests are skipped too (n8n's IMAP search has no NOT).
const addr = v => typeof v === 'string' ? v : (v?.text || v?.value?.[0]?.address || '');
const isDemo = s => /@[^>\s]+\.example>?\s*$/i.test(s.trim());
return $input.all()
  .filter(it => (!DEMO_MODE || isDemo(addr(it.json.from))) && !addr(it.json.from).includes(MY_ADDRESS))
  .map(it => {
    const j = it.json;
    const body = String(j.textPlain || j.text || j.textHtml || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 700);
    return { json: { sender: addr(j.from), subject: j.subject || '', received: String(j.date || ''), body } };
  });
